import java.util.Scanner;

public class Main {
    static int getInt(Scanner sc) {
        while (true) {
            if (sc.hasNextInt()) {
                return sc.nextInt();
            } else {
                sc.next();
            }
        }
    }

    static final int MAXN = 505;
    static long[] factorial = new long[MAXN];
    static long[] inv_factorial = new long[MAXN];
    static long[][] F = new long[MAXN][MAXN];
    static long[][] G = new long[MAXN][MAXN];
    static long[] f = new long[MAXN];
    static long[] g = new long[MAXN];
    static int n, m, P, maxn;

    static long mod_pow(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % P;
            base = base * base % P;
            exp >>= 1;
        }
        return res;
    }

    static long comb(int x, int y) {
        if (x < y || y < 0) return 0;
        return factorial[x] * inv_factorial[y] % P * inv_factorial[x - y] % P;
    }

    static int sum_series(int x) {
        return x * (x + 1) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = getInt(sc);
        m = getInt(sc);
        P = getInt(sc);
        maxn = n + 1;

        factorial[0] = 1;
        inv_factorial[0] = 1;
        for (int i = 1; i <= maxn; ++i) {
            factorial[i] = factorial[i - 1] * i % P;
        }
        for (int i = 1; i <= maxn; ++i) {
            inv_factorial[i] = mod_pow(factorial[i], P - 2);
        }

        f[0] = 1;
        for (int i = 1; i <= m; ++i) {
            for (int j = 0; j < i; ++j) {
                f[i] = (f[i] + f[j] * f[i - 1 - j] % P * comb(i - 1, j)) % P;
                g[i] = (g[i] + (((g[j] * f[i - 1 - j]) % P + (f[j] * g[i - 1 - j]) % P) * (i + 1) % P
                        + f[j] * f[i - 1 - j] % P * (sum_series(j) + sum_series(i - 1 - j))) % P * comb(i - 1, j)) % P;
            }
            f[i] = f[i] * (i + 1) % P;
        }

        for (int i = 0; i < MAXN; ++i) {
            for (int j = 0; j < MAXN; ++j) {
                F[i][j] = 0;
                G[i][j] = 0;
            }
        }
        F[0][0] = 1;
        for (int j = 0; j <= n; ++j) F[0][j] = 1;
        for (int i = 1; i <= m; ++i) {
            F[i][i] = f[i];
            G[i][i] = g[i];
            for (int j = i + 1; j <= n; ++j) {
                F[i][j] = F[i][j - 1];
                G[i][j] = G[i][j - 1];
                for (int l = 1; l <= i; ++l) {
                    F[i][j] = (F[i][j] + F[i - l][j - 1 - l] * f[l] % P * comb(i, l)) % P;
                    G[i][j] = (G[i][j] + (G[i - l][j - 1 - l] * f[l] % P + F[i - l][j - 1 - l] * g[l] % P) * comb(i, l)) % P;
                }
            }
        }
        System.out.println(G[m][n]);
        sc.close();
    }
}
